"""Presentation layer for the existing EkGuru /learn/ generator.
All catalogue rows originate in the original generator's validated registry.
No new routes, indexing decisions, counts or course-completion claims.
"""
from html import escape
from html.parser import HTMLParser
from urllib.parse import urlsplit

class Links(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True); self.links=[]; self.current=None
    def handle_starttag(self, tag, attrs):
        if tag=='a':
            self.current=[dict(attrs).get('href',''),[]]
    def handle_data(self,data):
        if self.current is not None: self.current[1].append(data)
    def handle_endtag(self,tag):
        if tag=='a' and self.current is not None:
            url, text=self.current; self.links.append((url,' '.join(''.join(text).split()))); self.current=None

def render_catalogue(indian, world, counts, old_region, href):
    e=lambda value:escape(str(value),quote=True)
    out=['<!-- ekguru:learn-index:start -->','<!-- Generated by tools/build-learn-index.py + lib/learn_catalogue_v3.py -->',
         '<link rel="stylesheet" href="../css/learn-catalogue-v3.css">',
         '<script src="../js/learn-catalogue-v3.js" defer></script>',
         '<div class="eg-learn-catalogue">']
    a=out.append
    a('<div class="lc-top"><p class="lc-intro">Read. Listen. Speak. Write.</p><a class="lc-progress" href="my-learning/">My learning <span aria-hidden="true">↗</span></a></div>')
    a('<div class="lc-toolbar" hidden><label for="lc-search">Find a language</label><div class="lc-search"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4.5 4.5"/></svg><input id="lc-search" type="search" autocomplete="off" placeholder="Search Hindi, বাংলা, Spanish…"><button type="button" class="lc-clear" hidden>Clear</button></div><div class="lc-filters" role="group" aria-label="Language category"><button type="button" data-lc-filter="all" aria-pressed="true">All <span data-lc-total="all"></span></button><button type="button" data-lc-filter="indian" aria-pressed="false">Indian <span data-lc-total="indian"></span></button><button type="button" data-lc-filter="world" aria-pressed="false">World <span data-lc-total="world"></span></button></div></div>')
    a('<p class="lc-status" aria-live="polite" hidden></p>')
    a('<section class="lc-section" id="li-indian" data-lc-section="indian" aria-labelledby="lc-indian-title"><div class="lc-section-head"><div><span class="lc-eyebrow">India · भाषा</span><h2 id="lc-indian-title">Languages of India</h2></div><span class="lc-count">'+str(len(indian)+1)+' languages</span></div>')
    a('<a id="li-hindi" class="lc-feature" data-lc-card data-lc-group="indian" data-lc-search="hindi हिंदी devanagari hi" href="'+e(href('learn/hindi'))+'"><div class="lc-feature-copy"><span class="lc-feature-label">Start here · Hindi</span><span class="lc-feature-native" lang="hi">हिंदी</span><h3>Hindi</h3><p>अक्षर से अभिव्यक्ति तक।<br><span lang="en">From your first letter to conversation.</span></p><span class="lc-open">Open Hindi <span aria-hidden="true">→</span></span></div><div class="lc-feature-art" aria-hidden="true"><img src="../images/learn-catalogue/hindi-book.svg" width="400" height="240" alt=""><span class="lc-art-a" lang="hi">अ</span><span class="lc-art-b" lang="hi">क</span><span class="lc-art-c" lang="hi">नमस्ते</span><span class="lc-orbit lc-orbit-one"></span><span class="lc-orbit lc-orbit-two"></span><span class="lc-spark lc-spark-one">✦</span><span class="lc-spark lc-spark-two">✧</span></div></a>')
    a('<div class="lc-grid">')
    primary={href('learn/hindi')}
    colors=['terracotta','teal','ochre','plum','blue','rose','green']
    for i,(slug,code,name,native,levels,topics,labs,r) in enumerate(indian):
        link=href('learn/'+slug); primary.add(link)
        a(f'<a class="lc-card li-card lc-{colors[i%len(colors)]}" data-lc-card data-lc-group="indian" data-lc-search="{e(name+" "+native+" "+code+" "+slug)}" href="{e(link)}"><span class="lc-script" lang="{e(code)}" dir="auto">{e(native)}</span><span class="lc-card-bottom"><span><strong>{e(name)}</strong><span class="lc-card-sub">View course</span></span><span class="lc-arrow" aria-hidden="true">→</span></span></a>')
    a('</div><button class="lc-more-languages" type="button" hidden>Show more languages</button></section>')
    a('<section class="lc-section" id="li-world" data-lc-section="world" aria-labelledby="lc-world-title"><div class="lc-section-head"><div><span class="lc-eyebrow">Global collection</span><h2 id="lc-world-title">Explore the world</h2></div><span class="lc-count">'+str(len(world))+' languages</span></div><div class="lc-grid lc-world-grid">')
    for i,(code,name,native,course,lessons,r,extras) in enumerate(world):
        link=href(course); primary.add(link)
        a(f'<a class="lc-card li-card lc-{colors[i%len(colors)]}" data-lc-card data-lc-group="world" data-lc-search="{e(name+" "+native+" "+code)}" href="{e(link)}"><span class="lc-script" lang="{e(code)}" dir="auto">{e(native)}</span><span class="lc-card-bottom"><span><strong>{e(name)}</strong><span class="lc-card-sub">View course</span></span><span class="lc-arrow" aria-hidden="true">→</span></span></a>')
    a('</div><button class="lc-more-languages" type="button" hidden>Show more languages</button></section><p class="lc-empty" hidden>No languages match your search. Try another name.</p>')
    a('<section class="lc-section lc-resources" id="li-shared" aria-labelledby="lc-resource-title"><div class="lc-section-head"><div><span class="lc-eyebrow">Your study space</span><h2 id="lc-resource-title">Study your way</h2></div></div><div class="lc-quick">')
    quick=[('learn/practice','Practice','Try exercises','01'),('materials','Worksheets','Print and write','02'),('toolbox','Learning tools','Explore scripts and words','03'),('learn/progress','My progress','Review your learning','04')]
    for route,title,sub,num in quick:
        link=href(route)
        a(f'<a href="{e(link)}"><span class="lc-resource-num">{num}</span><strong>{title}</strong><span>{sub}</span></a>'); primary.add(link)
    a('</div>')
    # Preserve unique pre-existing resource destinations (including long-form guides) without
    # restoring the duplicated directories to the default view. Safe local links only.
    parser=Links(); parser.feed(old_region); seen=set(primary); links=[]
    for url,label in parser.links:
        parts=urlsplit(url)
        if not url or url.startswith('#') or url in seen or parts.scheme or parts.netloc: continue
        if url.startswith('//'): continue
        seen.add(url); links.append((url,label or url))
    a('<details class="lc-more"><summary>More learning resources <span aria-hidden="true">+</span></summary><ul>')
    for url,label in links: a(f'<li><a href="{e(url)}">{e(label)}</a></li>')
    a('</ul></details></section>')
    a('<div id="li-tutors" class="lc-tutor"><span>Prefer personal guidance?</span><a href="../find-tutors.html">Find an independent Hindi tutor →</a></div>')
    a('<p class="lc-editorial">Free self-paced materials. Coverage varies by language; native-speaker review is not recorded. <a href="../editorial-policy/">Editorial policy and corrections</a>.</p>')
    a('</div><!-- ekguru:learn-index:end -->')
    return '\n'.join(out)
